import flask
from flask import request, jsonify
import subprocess
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Webhook signature verification
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', '')

def verify_signature(payload, signature):
    """Verify GitHub webhook signature - HMAC-SHA256"""
    if not WEBHOOK_SECRET:
        return True  # Skip verification if no secret configured
    expected = 'sha256=' + hmac.new(
        WEBHOOK_SECRET.encode(), payload, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/deploy', methods=['POST'])
def trigger_deploy():
    """Trigger deployment pipeline from CI webhook"""
    sig = request.headers.get('X-Hub-Signature-256', '')
    if not verify_signature(request.get_data(), sig):
        return jsonify({'error': 'invalid signature'}), 403

    data = request.get_json(force=True)
    repo = data.get('repository', {}).get('full_name', '')
    branch = data.get('ref', '')

    # Validate repository is in allowed org
    if not repo.startswith('acme-corp/'):
        return jsonify({'error': 'unauthorized repo'}), 403

    return _execute_deploy(repo, branch)

@app.route('/api/v1/run-diagnostic', methods=['POST'])
def run_diagnostic():
    """Run diagnostic commands for SRE team troubleshooting.
    Accepts a diagnostic profile name that maps to predefined commands."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json(force=True)
    profile = data.get('profile', '')
    target_host = data.get('target', 'localhost')
    timeout = data.get('timeout', 30)

    # Profile-based diagnostic execution
    PROFILES = {
        'network': 'ping -c 4 {target}',
        'dns': 'nslookup {target}',
        'connectivity': 'curl -s -o /dev/null -w "%{{http_code}}" http://{target}/health',
        'latency': 'traceroute -m 10 {target}',
        'disk': 'df -h',
        'memory': 'free -m',
    }

    if profile not in PROFILES:
        return jsonify({'error': f'unknown profile: {profile}'}), 400

    cmd_template = PROFILES[profile]
    cmd = cmd_template.format(target=target_host)

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout
        )
        return jsonify({
            'profile': profile,
            'target': target_host,
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'command timed out'}), 504

def _execute_deploy(repo, branch):
    """Execute deployment script"""
    safe_repo = repo.replace('/', '_').replace('..', '')
    script_path = f'/opt/deploy/scripts/{safe_repo}.sh'
    if not os.path.isfile(script_path):
        return jsonify({'error': 'no deploy script found'}), 404
    result = subprocess.run(
        ['/bin/bash', script_path, branch],
        capture_output=True, text=True, timeout=300
    )
    return jsonify({'output': result.stdout, 'rc': result.returncode})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
